// Deploy guard: prove a stored precache entry equals a live rerun.
//
// The entire cache rests on one claim -- "the optimizer is deterministic, so a
// stored result is exactly what the worker would produce" -- and until now that
// claim was a comment in tl-optimizer-precache.js, never a test.
// optimizer-precache.test.mjs checks that the cache is FRESH and that stored
// builds are LEGAL. Neither is the same as being RIGHT: a stale-but-legal build
// generated by different code passes both while serving cached players numbers
// the live engine no longer agrees with.
//
// This reruns the real adapter against the stored canonical request and
// compares the results.
//
// It deliberately runs WITHOUT a worker pool while the generator runs with
// four, so a pass proves more than replay: the same request produced the same
// bytes single-threaded on one machine and 4-way parallel on another. If
// parallelism or host ever leaked into a result, this is what would catch it.
// The cost is speed -- measured 409s for one entry here against ~57s to
// generate it -- so this is a gate check, not part of `npm test`, and --all is
// best run on a spare machine.
//
//   node scripts/verify-precache-determinism.mjs [--entry=<file>] [--all]
import { existsSync, readFileSync, readdirSync } from "node:fs";
import path from "node:path";
import { performance } from "node:perf_hooks";

import * as core from "../web/tl-core.js";
import { createOptimizerAdapter } from "../web/optimizer/tl-full-build-adapter.js";
import { canonicalPrecacheRequest, precacheKey } from "../web/optimizer/tl-optimizer-precache.js";
import { loadWebDataFromFile } from "./lib/load-web-projections.mjs";

const arg = (name) => process.argv.find((row) => row.startsWith(`--${name}=`))?.slice(name.length + 3);
const all = process.argv.includes("--all");
const cacheDir = path.resolve("web/data/optimizer-precache");
const indexPath = path.join(cacheDir, "index.json");

if (!existsSync(indexPath)) {
  console.log("precache determinism: no committed index — nothing to verify. OK.");
  process.exit(0);
}

const data = await loadWebDataFromFile(path.resolve("web/data/app-data.json"));
await core.initCore(data);
const adapter = await createOptimizerAdapter({ core, storage: {}, loadArmoryState: () => ({ ok: false }) });

const index = JSON.parse(readFileSync(indexPath, "utf8"));
const files = readdirSync(cacheDir).filter((name) => name !== "index.json" && name.endsWith(".json")).sort();
const chosen = arg("entry") ? [arg("entry")] : all ? files : files.slice(0, 1);

// The stored canonical form has no build (the cache is keyed on requests whose
// build is empty by definition), so rebuild the full request around a fresh
// scratch build. If this reconstruction is not equivalent the comparison is
// meaningless, so the derived key is checked against the stored one first.
function requestFrom(canonical, build) {
  return {
    build,
    sourceKind: "scratch",
    weaponTypes: canonical.weaponTypes,
    attributePointBudget: canonical.attributePointBudget,
    goals: { priorities: canonical.priorities, protect: [] },
    lockedSlotIds: [],
    progression: canonical.progression,
    rules: canonical.rules,
    depth: "thorough",
  };
}

// Report WHERE two results diverge, not just that they do — a boolean failure
// on a 100KB object is not actionable.
function firstDifference(left, right, trail = "result") {
  if (left === right) return null;
  if (typeof left !== typeof right || left === null || right === null) return `${trail}: ${JSON.stringify(left)?.slice(0, 60)} vs ${JSON.stringify(right)?.slice(0, 60)}`;
  if (typeof left !== "object") return `${trail}: ${JSON.stringify(left)} vs ${JSON.stringify(right)}`;
  if (Array.isArray(left) !== Array.isArray(right)) return `${trail}: array/object mismatch`;
  if (Array.isArray(left) && left.length !== right.length) return `${trail}.length: ${left.length} vs ${right.length}`;
  const keys = new Set([...Object.keys(left), ...Object.keys(right)]);
  for (const key of keys) {
    const nested = firstDifference(left[key], right[key], `${trail}.${key}`);
    if (nested) return nested;
  }
  return null;
}

let failures = 0;
for (const fileName of chosen) {
  const entryPath = path.join(cacheDir, fileName);
  if (!existsSync(entryPath)) { console.error(`MISSING ${fileName}`); failures++; continue; }
  const entry = JSON.parse(readFileSync(entryPath, "utf8"));

  const build = await adapter.createScratchBuild();
  const request = requestFrom(entry.canonicalRequest, build);
  const canonical = canonicalPrecacheRequest(request);
  if (!canonical) { console.error(`FAIL ${fileName}: reconstructed request is not cache-eligible`); failures++; continue; }
  const key = await precacheKey(canonical, index.gameBuild);
  if (key !== entry.key) {
    console.error(`FAIL ${fileName}: reconstruction does not re-derive the stored key — the comparison below would be meaningless`);
    failures++;
    continue;
  }

  const startedAt = performance.now();
  const live = JSON.parse(JSON.stringify(await adapter.optimize(request)));
  // The generator drops tuningFrontier before storing; a live run still carries
  // it. Compare on the same footing rather than reporting a known difference.
  delete live.tuningFrontier;
  const elapsed = Math.round(performance.now() - startedAt);

  const difference = firstDifference(live, entry.result);
  if (difference) {
    console.error(`FAIL ${fileName} (${elapsed}ms): live rerun differs from stored`);
    console.error(`  first difference at ${difference}`);
    failures++;
  } else {
    console.log(`ok   ${fileName} (${elapsed}ms) — live rerun is identical to stored`);
  }
}

if (failures) {
  console.error(`\n${failures} of ${chosen.length} entries do not reproduce.`);
  console.error("Cached players would receive different numbers than live players.");
  process.exit(1);
}
console.log(`\nprecache determinism: ${chosen.length} of ${files.length} entries verified identical.`);
